# owner: platform
"""Plain text absence notices for parents."""

from datetime import date
from typing import Iterable, List

from rosterkit.attendance import days_missed
from rosterkit.models import Mark, Student

def _format_day(stamp: date) -> str:
    return f"{stamp:%B} {stamp.day}, {stamp.year}"

def _check_owner(student: Student, marks: List[Mark]):
    """Refuse marks that belong to someone else."""
    for mark in marks:
        other = mark.student_id
        if other != student.student_id:
            raise ValueError(f"foreign mark: {other}")

def _intro(student: Student, count: int) -> str:
    noun = "day" if count == 1 else "days"
    name = f"{student.first_name} {student.last_name}"
    return f"{name} missed {count} {noun} of class:"

def _compose(student: Student, days: List[date]) -> str:
    """Put the name, the count and the dates in order."""
    if not days:
        raise ValueError("no absences to write about")
    lines = [_intro(student, len(days))]
    lines += [f"- {_format_day(stamp)}" for stamp in days]
    return "\n".join(lines)

# ---
def build_absence_notice(
    student: Student, marks: Iterable[Mark]
) -> str:
    """Write a short notice listing each absent day."""
    marks = list(marks)
    _check_owner(student, marks)
    return _compose(student, days_missed(marks))
